#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, sz;
    DSU(int n) {
        parent.resize(n + 1);
        sz.assign(n + 1, 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> adj(N + 1);
    DSU dsu(N);

    for (int i = 0; i < M; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
        dsu.unite(u, v);
    }

    for (int i = 1; i <= N; i++) {
        sort(adj[i].begin(), adj[i].end());
    }

    vector<vector<int>> comps(N + 1);
    for (int i = 1; i <= N; i++) {
        comps[dsu.find(i)].push_back(i);
    }

    for (int root = 1; root <= N; root++) {
        if (comps[root].empty()) continue;

        int s = (int)comps[root].size();
        if (s <= 1) continue;

        int v = -1;
        for (int x : comps[root]) {
            if ((int)adj[x].size() < s - 1) {
                v = x;
                break;
            }
        }

        if (v != -1) {
            for (int u : comps[root]) {
                if (u == v) continue;
                if (!binary_search(adj[v].begin(), adj[v].end(), u)) {
                    cout << v << ' ' << u << '\n';
                    return 0;
                }
            }
        }
    }

    cout << -1 << '\n';
    return 0;
}
